//! Парсер командной строки в стиле hashcat.
//!
//! Поддерживаются длинные (`--hash-type 0`, `--hash-type=0`) и короткие
//! (`-m 0`, `-m0`) флаги. Всё разбирается вручную — без внешних зависимостей,
//! чтобы поведение было предсказуемым.

use std::path::PathBuf;

use crate::hash::HashType;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AttackMode {
    /// 0 — словарь: каждая строка из wordlist пробуется как пароль.
    Straight,
    /// 1 — комбинатор: wordlist + wordlist2, конкатенация пар.
    Combinator,
    /// 3 — брутфорс по маске (?l ?d ?a и т.д.).
    BruteForce,
}

impl AttackMode {
    pub fn code(self) -> u32 {
        match self {
            AttackMode::Straight => 0,
            AttackMode::Combinator => 1,
            AttackMode::BruteForce => 3,
        }
    }

    pub fn from_code(code: u32) -> Result<Self, String> {
        match code {
            0 => Ok(AttackMode::Straight),
            1 => Ok(AttackMode::Combinator),
            3 => Ok(AttackMode::BruteForce),
            other => Err(format!(
                "неподдерживаемый режим атаки -a {} (доступно: 0=straight, 1=combinator, 3=brute-force)",
                other
            )),
        }
    }
}

#[derive(Debug, Clone)]
pub struct Config {
    /// Hex-хеши из --hash.
    pub hashes: Vec<String>,
    /// Файл с хешами (по одному на строку, можно с суффиксом `:метаданные`).
    pub hash_file: Option<PathBuf>,
    pub hash_type: HashType,
    pub attack: AttackMode,
    pub wordlist: Option<PathBuf>,
    pub wordlist2: Option<PathBuf>,
    pub mask: Option<String>,
    pub custom_charsets: [Option<String>; 4],
    pub increment: bool,
    pub increment_min: usize,
    pub increment_max: Option<usize>,
    pub threads: usize,
    pub outfile: PathBuf,
    pub no_potfile: bool,
    pub show: bool,
    pub status: bool,
    pub status_timer: u64,
    pub quiet: bool,
    pub verbose: bool,
    pub self_test: bool,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            hashes: Vec::new(),
            hash_file: None,
            hash_type: HashType::Md5,
            attack: AttackMode::BruteForce,
            wordlist: None,
            wordlist2: None,
            mask: None,
            custom_charsets: [None, None, None, None],
            increment: false,
            increment_min: 1,
            increment_max: None,
            threads: 0, // 0 = автодетект в main
            outfile: PathBuf::from("rust_hashcat.potfile"),
            no_potfile: false,
            show: false,
            status: false,
            status_timer: 5,
            quiet: false,
            verbose: false,
            self_test: false,
        }
    }
}

/// Результат парсинга: либо конфиг, либо команда-флаг (help/version), либо ошибка.
pub enum ParseResult {
    Run(Config),
    Help,
    Version,
}

pub fn parse_args(args: &[String]) -> Result<ParseResult, String> {
    let mut cfg = Config::default();
    let mut i = 0;

    // Простой пре-скан: --help/-H и --version/-V без обязательных аргументов.
    if args.iter().any(|a| a == "--help" || a == "-H") {
        return Ok(ParseResult::Help);
    }
    if args.iter().any(|a| a == "--version" || a == "-V") {
        return Ok(ParseResult::Version);
    }

    while i < args.len() {
        let arg = &args[i];
        // Длинный флаг с '=': --hash-type=0
        let (name, inline_val) = match arg.split_once('=') {
            Some((n, v)) if n.starts_with("--") => (n.to_string(), Some(v.to_string())),
            _ => (arg.clone(), None),
        };
        // Короткий флаг со слитым значением: -m0, -a3 → ключ "-m", значение "0".
        let (key, short_val) = if name.starts_with('-') && !name.starts_with("--") && name.len() > 2 {
            (name[..2].to_string(), Some(name[2..].to_string()))
        } else {
            (name.clone(), inline_val)
        };

        // next() берёт следующее значение, если не задано инлайном.
        let next_val = |i: &mut usize| -> Result<String, String> {
            if let Some(v) = short_val.clone() {
                return Ok(v);
            }
            *i += 1;
            if *i >= args.len() {
                return Err(format!("флагу '{}' не хватает значения", key));
            }
            Ok(args[*i].clone())
        };

        match key.as_str() {
            "-h" | "--hash" => cfg.hashes.push(next_val(&mut i)?),
            "--hash-file" => cfg.hash_file = Some(PathBuf::from(next_val(&mut i)?)),
            "-m" | "--hash-type" => {
                let v = next_val(&mut i)?;
                let code: u32 = v
                    .parse()
                    .map_err(|_| format!("-m ожидает число, получено '{}'", v))?;
                cfg.hash_type = HashType::from_code(code)?;
            }
            "-a" | "--attack-mode" => {
                let v = next_val(&mut i)?;
                let code: u32 = v
                    .parse()
                    .map_err(|_| format!("-a ожидает число, получено '{}'", v))?;
                cfg.attack = AttackMode::from_code(code)?;
            }
            "-w" | "--wordlist" => cfg.wordlist = Some(PathBuf::from(next_val(&mut i)?)),
            "--wordlist2" => cfg.wordlist2 = Some(PathBuf::from(next_val(&mut i)?)),
            "-M" | "--mask" => cfg.mask = Some(next_val(&mut i)?),
            "-1" | "--custom-charset1" => cfg.custom_charsets[0] = Some(next_val(&mut i)?),
            "-2" | "--custom-charset2" => cfg.custom_charsets[1] = Some(next_val(&mut i)?),
            "-3" | "--custom-charset3" => cfg.custom_charsets[2] = Some(next_val(&mut i)?),
            "-4" | "--custom-charset4" => cfg.custom_charsets[3] = Some(next_val(&mut i)?),
            "-i" | "--increment" => cfg.increment = true,
            "--increment-min" => {
                let v = next_val(&mut i)?;
                cfg.increment_min = v
                    .parse()
                    .map_err(|_| format!("--increment-min ожидает число, получено '{}'", v))?;
            }
            "--increment-max" => {
                let v = next_val(&mut i)?;
                cfg.increment_max = Some(
                    v.parse()
                        .map_err(|_| format!("--increment-max ожидает число, получено '{}'", v))?,
                );
            }
            "-T" | "--threads" => {
                let v = next_val(&mut i)?;
                cfg.threads = v
                    .parse()
                    .map_err(|_| format!("--threads ожидает число, получено '{}'", v))?;
                if cfg.threads == 0 {
                    return Err("--threads должен быть >= 1".to_string());
                }
            }
            "-o" | "--outfile" => cfg.outfile = PathBuf::from(next_val(&mut i)?),
            "--no-potfile" => cfg.no_potfile = true,
            "--show" => cfg.show = true,
            "-s" | "--status" => cfg.status = true,
            "--status-timer" => {
                let v = next_val(&mut i)?;
                cfg.status_timer = v
                    .parse()
                    .map_err(|_| format!("--status-timer ожидает число, получено '{}'", v))?;
            }
            "-q" | "--quiet" => cfg.quiet = true,
            "-v" | "--verbose" => cfg.verbose = true,
            "--self-test" => cfg.self_test = true,
            "-H" | "--help" => return Ok(ParseResult::Help),
            "-V" | "--version" => return Ok(ParseResult::Version),
            other => return Err(format!("неизвестный флаг '{}' (--help для списка)", other)),
        }
        i += 1;
    }

    Ok(ParseResult::Run(cfg))
}

/// Валидация после парсинга: обязательные поля, несовместимости.
pub fn validate(cfg: &Config) -> Result<(), String> {
    if cfg.show {
        // --show не требует хешей — читает potfile.
        return Ok(());
    }
    if cfg.self_test {
        return Ok(());
    }
    if cfg.hashes.is_empty() && cfg.hash_file.is_none() {
        return Err("не задан хеш: используйте --hash <HEX> или --hash-file <ФАЙЛ>".to_string());
    }
    if cfg.increment_min == 0 {
        return Err("--increment-min должен быть >= 1".to_string());
    }
    match cfg.attack {
        AttackMode::Straight => {
            if cfg.wordlist.is_none() {
                return Err("-a 0 (straight) требует --wordlist <ФАЙЛ>".to_string());
            }
        }
        AttackMode::Combinator => {
            if cfg.wordlist.is_none() || cfg.wordlist2.is_none() {
                return Err("-a 1 (combinator) требует --wordlist и --wordlist2".to_string());
            }
        }
        AttackMode::BruteForce => {
            if cfg.mask.is_none() {
                return Err("-a 3 (brute-force) требует --mask, например --mask '?d?d?d?d'".to_string());
            }
        }
    }
    if cfg.status_timer == 0 {
        return Err("--status-timer должен быть >= 1".to_string());
    }
    Ok(())
}

