#[cfg(test)]
mod tests {
    use super::*;

    fn args(v: &[&str]) -> Vec<String> {
        v.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn parse_basic_bruteforce() {
        let cfg = match parse_args(&args(&[
            "--hash", "abc123", "-m", "0", "-a", "3", "--mask", "?d?d?d",
        ]))
        .unwrap()
        {
            ParseResult::Run(c) => c,
            _ => panic!("ожидался Run"),
        };
        assert_eq!(cfg.hashes, vec!["abc123"]);
        assert_eq!(cfg.hash_type, HashType::Md5);
        assert_eq!(cfg.attack, AttackMode::BruteForce);
        assert_eq!(cfg.mask.as_deref(), Some("?d?d?d"));
    }

    #[test]
    fn parse_short_attached_values() {
        let cfg = match parse_args(&args(&["-m0", "-a3", "-M?d?d", "-hdeadbeef"])).unwrap() {
            ParseResult::Run(c) => c,
            _ => panic!("ожидался Run"),
        };
        assert_eq!(cfg.hash_type, HashType::Md5);
        assert_eq!(cfg.attack, AttackMode::BruteForce);
        assert_eq!(cfg.mask.as_deref(), Some("?d?d"));
        assert_eq!(cfg.hashes, vec!["deadbeef"]);
    }

    #[test]
    fn parse_equals_form() {
        let cfg = match parse_args(&args(&["--hash-type=1400", "--hash=x"])) .unwrap() {
            ParseResult::Run(c) => c,
            _ => panic!("ожидался Run"),
        };
        assert_eq!(cfg.hash_type, HashType::Sha256);
    }

    #[test]
    fn parse_increment_and_threads() {
        let cfg = match parse_args(&args(&[
            "--hash", "x", "-m", "0", "-a", "3", "--mask", "?d?d?d?d",
            "-i", "--increment-min", "2", "--increment-max", "4", "-T", "8",
        ]))
        .unwrap()
        {
            ParseResult::Run(c) => c,
            _ => panic!("ожидался Run"),
        };
        assert!(cfg.increment);
        assert_eq!(cfg.increment_min, 2);
        assert_eq!(cfg.increment_max, Some(4));
        assert_eq!(cfg.threads, 8);
    }

    #[test]
    fn parse_straight() {
        let cfg = match parse_args(&args(&["-h", "x", "-m", "0", "-a", "0", "-w", "dict.txt"])).unwrap() {
            ParseResult::Run(c) => c,
            _ => panic!("ожидался Run"),
        };
        assert_eq!(cfg.attack, AttackMode::Straight);
        assert_eq!(cfg.wordlist.as_deref(), Some(std::path::Path::new("dict.txt")));
    }

    #[test]
    fn parse_combinator() {
        let cfg = match parse_args(&args(&[
            "-h", "x", "-m", "0", "-a", "1", "-w", "a.txt", "--wordlist2", "b.txt",
        ]))
        .unwrap()
        {
            ParseResult::Run(c) => c,
            _ => panic!("ожидался Run"),
        };
        assert_eq!(cfg.attack, AttackMode::Combinator);
    }

    #[test]
    fn parse_unknown_flag_errors() {
        assert!(parse_args(&args(&["--nope"])).is_err());
    }

    #[test]
    fn parse_missing_value_errors() {
        assert!(parse_args(&args(&["--hash"])).is_err());
    }

    #[test]
    fn parse_help_and_version() {
        assert!(matches!(parse_args(&args(&["-H"])).unwrap(), ParseResult::Help));
        assert!(matches!(
            parse_args(&args(&["--version"])).unwrap(),
            ParseResult::Version
        ));
    }

    #[test]
    fn validate_requires_hash() {
        let cfg = Config::default();
        assert!(validate(&cfg).is_err());
    }

    #[test]
    fn validate_straight_needs_wordlist() {
        let mut cfg = Config::default();
        cfg.hashes.push("x".into());
        cfg.attack = AttackMode::Straight;
        assert!(validate(&cfg).is_err());
    }

    #[test]
    fn validate_combinator_needs_two_wordlists() {
        let mut cfg = Config::default();
        cfg.hashes.push("x".into());
        cfg.attack = AttackMode::Combinator;
        cfg.wordlist = Some(PathBuf::from("a"));
        assert!(validate(&cfg).is_err());
    }

    #[test]
    fn validate_bruteforce_needs_mask() {
        let mut cfg = Config::default();
        cfg.hashes.push("x".into());
        cfg.attack = AttackMode::BruteForce;
        assert!(validate(&cfg).is_err());
    }

    #[test]
    fn validate_ok() {
        let mut cfg = Config::default();
        cfg.hashes.push("x".into());
        cfg.mask = Some("?d?d".into());
        assert!(validate(&cfg).is_ok());
    }
}

